const float x = input * 1.5f;
if (abs(x) < 0.7f)
    return input;
if (x > 0.7f)
    return 0.7f + tanh((x - 0.7f) * 3.0f) * 0.3f;
return -0.7f + tanh((x + 0.7f) * 3.0f) * 0.3f;

const float x = input * 0.5f;
float output = input - 0.1f * x * x * x;
output *= (input > 0.0f) ? 0.98f : 1.02f;
return tanh(output * 1.2f) * 0.9f;

if (input > 0.0f)
    return input < 0.3f ? input : 0.3f + tanh((input - 0.3f) * 4.0f) * 0.4f;
if (input > -2.0f)
