float attackCoeff = std::exp(-1.0f / (attackMs * 0.001f * sampleRate));
float releaseCoeff = std::exp(-1.0f / (releaseMs * 0.001f * sampleRate));

float coeff = (inputLevelDB > linearToDb(envelope)) ? attackCoeff : releaseCoeff;
envelope = coeff * envelope + (1.0f - coeff) * inputLevel;

float kneeStart = threshold - knee / 2.0f;
float kneeEnd = threshold + knee / 2.0f;

if (inputLevelDB >= kneeEnd) {
  // Above knee: full compression
  float overDB = inputLevelDB - threshold;
  return overDB - (overDB / ratio);
} else {
  // In knee region: quadratic curve
  float kneeInput = inputLevelDB - kneeStart;
  float kneeRatio = kneeInput / knee;
  float overDB = inputLevelDB - threshold;
  float gainReduction = overDB - (overDB / ratio);
  return gainReduction * kneeRatio * kneeRatio;
}

// Calculate shelf coefficients
A = pow(10.0, gainDb / 40.0);  // Convert dB to linear
w0 = 2π * frequency / sampleRate;
alpha = sin(w0) / (2.0 * Q);
beta = sqrt(A) / Q;

// Biquad coefficients
a0 = (A+1) + (A-1)*cos(w0) + beta*sin(w0);
b0 = A*((A+1) - (A-1)*cos(w0) + beta*sin(w0)) / a0;
b1 = 2*A*((A-1) - (A+1)*cos(w0)) / a0;
b2 = A*((A+1) - (A-1)*cos(w0) - beta*sin(w0)) / a0;

// Peaking filter for mid band
A = pow(10.0, gainDb / 40.0);
w0 = 2π * frequency / sampleRate;
alpha = sin(w0) / (2.0 * Q);

